return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'ug_CN','project-id-version'=>'Babilim 1.2.3','pot-creation-date'=>'2026-11-09T07:54:40+00:00','po-revision-date'=>'2026-11-09T07:54:40+00:00','x-generator'=>'Babilim','messages'=>['Sent when you press Enable Babilim, and again if the site has to register anew: your site\'s URL, the WordPress, PHP and Babilim versions, the language of your site and the languages in use on it, and a public key generated for this site.'=>'Babilim نى قوزغىتىش نى باسقىنىڭىزدا، شۇنداقلا بېكەت قايتا تىزىملىتىشقا توغرا كەلگەندە يوللىنىدۇ: بېكىتىڭىزنىڭ URL ى، WordPress، PHP ۋە Babilim نەشرى، بېكىتىڭىزنىڭ تىلى ۋە ئۇنىڭدا ئىشلىتىلىۋاتقان تىللار، ھەمدە بۇ بېكەت ئۈچۈن ھاسىل قىلىنغان ئاشكارا kalıt.','Sent on every check: the list of installed plugins and themes with the state of any Babilim translation installed for them, the languages in use, and short diagnostic codes.'=>'ھەر قېتىملىق تەكشۈرۈشتە يوللىنىدۇ: ئورنىتىلغان قىستۇرمىلار ۋە ئۆرنەكلەرنىڭ تىزىملىكى ھەمدە ئۇلار ئۈچۈن ئورنىتىلغان Babilim تەرجىمىسىنىڭ ھالىتى، ئىشلىتىلىۋاتقان تىللار ۋە قىسقا دىئاگنوستىكا كودلىرى.','Every request includes your site\'s URL, and the site\'s access token is included whenever the service needs it.'=>'ھەر بىر ئىلتىماس بېكىتىڭىزنىڭ URL ىنى ئۆز ئىچىگە ئالىدۇ، مۇلازىمەت لازىم تاپقاندا بېكەتنىڭ زىيارەت بەلگىسىمۇ قوشۇلىدۇ.','What Babilim sends to the service'=>'Babilim مۇلازىمەتكە نېمە يوللايدۇ','Your site\'s URL'=>'بېكىتىڭىزنىڭ URL ى','WordPress version'=>'WordPress نەشرى','PHP version'=>'PHP نەشرى','Babilim version'=>'Babilim نەشرى','Your site\'s language'=>'بېكىتىڭىزنىڭ تىلى','Languages in use on your site'=>'بېكىتىڭىزدە ئىشلىتىلىۋاتقان تىللار','A public key for this site'=>'بۇ بېكەتنىڭ ئاشكارا kalıt ى','A public key generated for this site, used to prove requests genuinely come from this site. Only the public half is ever sent; the private half stays on your site.'=>'بۇ بېكەت ئۈچۈن ھاسىل قىلىنغان، ئىلتىماسلارنىڭ ھەقىقەتەن مۇشۇ بېكەتتىن كەلگەنلىكىنى ئىسپاتلاشقا ئىشلىتىلىدىغان ئاشكارا kalıt. پەقەت ئاشكارا قىسمى يوللىنىدۇ؛ شەخسىي قىسمى بېكىتىڭىزدە قالىدۇ.','Installed plugins and themes'=>'ئورنىتىلغان قىستۇرمىلار ۋە ئۆرنەكلەر','Source files (only if you confirm an upload)'=>'مەنبە ھۆججەتلىرى (پەقەت يوللاشنى جەزملىسىڭىزلا)','Diagnostic codes'=>'دىئاگنوستىكا كودلىرى','Up to 20 short diagnostic codes (for example, a translation file that failed its check), each with the plugin or theme, the language and the time it happened. They never contain any text from your site or any translated text.'=>'ئەڭ كۆپ بولغاندا 20 قىسقا دىئاگنوستىكا كودى (مەسىلەن، تەكشۈرۈشتىن ئۆتەلمىگەن تەرجىمە ھۆججىتى)، ھەر بىرى قىستۇرما ياكى ئۆرنەك، تىل ۋە يۈز بەرگەن ۋاقىت بىلەن بىرگە. ئۇلار ھەرگىز بېكىتىڭىزدىكى ياكى تەرجىمە قىلىنغان ھېچقانداق تېكىستنى ئۆز ئىچىگە ئالمايدۇ.','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'بۇ كۆپ تور بېكەتلىك تورداتىكى %1$d تور بېكەت قىستۇرما ئۆچۈرۈلگەندە ئۆزىنىڭ Babilim كىملىكىنى ئۆچۈرۈۋېتىشكە تەڭشەلگەن. ئۇنىڭدىن كېيىن ئۇ تور بېكەتكە باغلانغان ھەقلىق ئىجازەتنامىنى ئاپتوماتىك ئەسلىگە كەلتۈرگىلى بولمايدۇ؛ ئۇنى قايتۇرۇۋېلىش ئۈچۈن Babilim قوللىشى بىلەن %2$s ئارقىلىق ئالاقىلىشىشىڭىز كېرەك. كىملىكنى ساقلاپ قېلىش ئۈچۈن «ۋاز كېچىش» نى چېكىڭ، ئۇ تور بېكەتنىڭ Babilim تەڭشەكلىرىدىكى «ئورنىتىلمىغاندا Babilim نىڭ بارلىق سانلىق مەلۇماتلىرىنى ئۆچۈرۈش» تاللانمىسىدىكى بەلگىنى ئېلىۋېتىڭ، ئاندىن قايتا توختىتىڭ. بەرىبىر توختىتامسىز؟' . "\0" . 'بۇ كۆپ تور بېكەتلىك تورداتىكى %1$d تور بېكەت قىستۇرما ئۆچۈرۈلگەندە ئۆزىنىڭ Babilim كىملىكىنى ئۆچۈرۈۋېتىشكە تەڭشەلگەن. ئۇنىڭدىن كېيىن ئۇ تور بېكەتلەرگە باغلانغان ھەقلىق ئىجازەتنامىنى ئاپتوماتىك ئەسلىگە كەلتۈرگىلى بولمايدۇ؛ ئۇنى قايتۇرۇۋېلىش ئۈچۈن Babilim قوللىشى بىلەن %2$s ئارقىلىق ئالاقىلىشىشىڭىز كېرەك. كىملىكلەرنى ساقلاپ قېلىش ئۈچۈن «ۋاز كېچىش» نى چېكىڭ، ھەر بىر تور بېكەتنىڭ Babilim تەڭشەكلىرىدىكى «ئورنىتىلمىغاندا Babilim نىڭ بارلىق سانلىق مەلۇماتلىرىنى ئۆچۈرۈش» تاللانمىسىدىكى بەلگىنى ئېلىۋېتىڭ، ئاندىن قايتا توختىتىڭ. بەرىبىر توختىتامسىز؟','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s قىلىدىغان ئىش يوق.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. تىلنى تاللاڭ.','%d failed'=>'%d مەغلۇب بولدى' . "\0" . '%d مەغلۇب بولدى','%d not yet tried'=>'%d تېخى سىنالمىدى' . "\0" . '%d تېخى سىنالمىدى','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d دوكلات كۈتۈۋاتىدۇ. «ھەمىشە ھەمبەھىرلەش» ۋە «ھەمبەھىرلىمە» ھەممىسىگە قوللىنىلىدۇ.' . "\0" . '%d دوكلات كۈتۈۋاتىدۇ. «ھەمىشە ھەمبەھىرلەش» ۋە «ھەمبەھىرلىمە» ھەممىسىگە قوللىنىلىدۇ.','%d skipped'=>'%d ئاتلاپ ئۆتۈلدى' . "\0" . '%d ئاتلاپ ئۆتۈلدى','%d succeeded'=>'%d مۇۋەپپەقىيەتلىك بولدى' . "\0" . '%d مۇۋەپپەقىيەتلىك بولدى','%d to install'=>'%d ئورنىتىلىدۇ' . "\0" . '%d ئورنىتىلىدۇ','(a public key generated for this site)'=>'(بۇ تور بېكەت ئۈچۈن ھاسىل قىلىنغان ئاشكارا ئاچقۇچ)','(detected)'=>'(بايقالدى)','(generic codes and coordinates only)'=>'(پەقەت ئومۇمىي كودلار ۋە كوئوردېناتلار)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'%1$s دە تازىلاش توختىتىلدى: %2$s. ھېچnەرسە ئۆچۈرۈلمىدى.','A file in the component could not be read, so it was not packaged.'=>'زاپچاسنىڭ ئىچىدىكى بىر ھۆججەتنى ئوقۇغىلى بولمىدى، شۇڭا بوغچىلانمىدى.','A host that serves only one PHP request at a time cannot complete this step.'=>'بىرلا ۋاقىتتا پەقەت بىر PHP تەلىپىنى بىر تەرەپ قىلىدىغان ساھىبجاي بۇ باسقۇچنى تاماملىيالمايدۇ.','A part of the upload kept failing, so the upload was cancelled.'=>'يۈكلەشنىڭ بىر قىسمى توختىماي مەغلۇپ بولدى، شۇڭا يۈكلەش ئەمەلدىن قالدۇرۇلدى.','A translation cannot be requested for that locale on this site right now.'=>'ھازىر بۇ تور بېكەتتە بۇ تىل ئۈچۈن تەرجىمە تەلەپ قىلغىلى بولمايدۇ.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'تەرجىمە ئىندېكسىغا يېزىش %1$s دا (%2$s) باشقا باشقا تەلەپ بىلەن توقۇنۇشۇپ قالدى ۋە ئىجرا قىلىنمىدى؛ ئەڭ يېڭى نەشرى ساقلاندى.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'%1$s دىكى تەرجىمە ئىندېكسىغا يېزىش (%2$s) تاماملانمىدى ۋە ئىجرا قىلىنمىدى (%3$s).','Account'=>'ھېساباتىم','Add another language'=>'باشقا تىل قوشۇش','Advanced'=>'ئالىي','All'=>'ھەممىسى','All free-plan slots for this site are used'=>'بۇ بېكەتنىڭ بارلىق ھەقسىز پىلان ئورۇنلىرى ئىشلىتىلگەن','All languages'=>'بارلىق تىللار','Already in WordPress core'=>'WordPress يادروسىدا بار','Already installed.'=>'ئورنىتىلغان.','Always share'=>'ھەمىشە ھەمبەھىرلەش','Another installation is running; try again in a moment.'=>'باشقا بىر ئورنىتىش ئىجرا بولۇۋاتىدۇ؛ سەل تۇرۇپ قايتا سىناڭ.','Automatic installs'=>'ئاپتوماتىك ئورنىتىش','Automatic installs are now off; turn them on again in the settings if you want them.'=>'ئاپتوماتىك ئورنىتىش ھازىر تاقالدى؛ ئەگەر لازىم بولسا تەڭشەكلەردە قايتا ئېچىڭ.','Available'=>'ئىشلەتكىلى بولىدۇ','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'بار تەرجىمىلەرنى بىر چېكىش بىلەن ئورنىتىشقا، كەم تەرجىمىلەرنى تەلەپ قىلىشقا بولىدۇ. ئاپتوماتىك قاچىلاش ئوچۇق ۋاقىتتا، مۇلازىمەت سىز باشقۇرىدىغان تىللار ئۈچۈن بار دەپ كۆرسەتكەن تەرجىمىلەر كۈنىگە ئىككى قېتىم ماسقەدەملەش جەريانىدا قاچىلىنىدۇ.','Available · %s'=>'ئىشلەتكىلى بولىدۇ · %s','Babilim'=>'Babilim','Babilim Settings'=>'Babilim تەڭشەكلىرى','Babilim adds translations for every language checked here.'=>'Babilim بۇ يەردە تاللانغان ھەر بىر تىل ئۈچۈن تەرجىمە قوشىدۇ.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim تور بېكەتنىڭ سىرتىدىكى ۋاقىتلىق قىسقۇچنى جەزملىيەلمىدى، شۇڭا زاپچاس بوغچىلانمىدى ۋە ھېچقانداق نەرسە يۈكلەنمىدى. wp-config.php ئىچىدە BABILIM_TEMP_DIR نى تور يىلتىز مۇندەرىجىسىنىڭ سىرتىدىكى يېزىشقا بولىدىغان قىسقۇچ قىلىپ بەلگىلەڭ (مەسىلەن، سايتىڭىزنىڭ ئاممىۋى مۇندەرىجىسىنىڭ ئىچىدە ئەمەس، بەلكى ئۇنىڭ بىلەن يانمۇيان تۇرىدىغان قىسقۇچ)، ياكى مۇلازىمېتىر تەمىنلىگۈچىڭىزدىن بىرنى سوراڭ.','Babilim could not finish checking this site.'=>'Babilim بۇ تور بېكەتنى تەكشۈرۈپ بولالمىدى.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim قوزغىتىشنى تاماملىيالمىدى (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim بۇ بېكەتنى دەلىللەشنى تامامىلىيالمىدى (مۇلازىمەت ئۇنىڭغا قايتا ئۇلىنالمىدى). تىزىملاش توختىتىلدى.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim بۇ تور بېكەتنى دەلىللىيەلمىدى، شۇڭا دەلىللەش مۇۋەپپەقىيەتلىك بولغۇچە ھېچنېمە چۈشۈرۈلمەيدۇ ياكى قاچىلانمايدۇ.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim بۇ سایىتنى دەلىللىيەلمىدى، شۇڭا ھېچنېمە چۈشۈرۈلمەيدۇ ياكى ئورنىتىلمايدۇ.','Babilim gets translations from the Babilim service for the plugins and themes on this site that have none for your language, and installs the ones your service plan covers.'=>'Babilim بۇ بېكەتتىكى سىزنىڭ تىلىڭىزدا تەرجىمىسى يوق قىستۇرما ۋە ئۇسلۇبلار ئۈچۈن Babilim مۇلازىمىتىدىن تەرجىمىلەرنى ئالىدۇ ھەمدە مۇلازىمەت پىلانىڭىز ئۆز ئىچىگە ئالغانلىرىنى ئورنىتىدۇ.','Babilim has not been enabled for this site yet.'=>'Babilim بۇ تور بېكەتتە تېخى قوزغىتىلمىغان.','Babilim has not installed any translation for this language.'=>'Babilim بۇ تىل ئۈچۈن ھېچقانداق تەرجىمە ئورناتمىدى.','Babilim hit an error. Share an error report?'=>'Babilim دا خاتالىق يۈز بەردى. خاتالىق دوكلاتىنى ھەمبەھىرلەمسىز؟','Babilim installed %d translation automatically since your last visit.'=>'ئاخىرقى زىيارىتىڭىزدىن بۇيان Babilim %d تەرجىمىنى ئاپتوماتىك ئورناتتى.' . "\0" . 'ئاخىرقى زىيارىتىڭىزدىن بۇيان Babilim %d تەرجىمىنى ئاپتوماتىك ئورناتتى.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim ئوچۇرۇلدى. ئەمدى ھېچنېمە ئەۋەتىلمەيدۇ؛ ئورنىتىلغان تەرجىمىلەر داۋاملىق ئىشلەيدۇ.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim قوزغىتىلدى: بۇ تور بېكەت دەلىللەندى ۋە %d زاپچاس تېپىلدى.' . "\0" . 'Babilim قوزغىتىلدى: بۇ تور بېكەت دەلىللەندى ۋە %d زاپچاس تېپىلدى.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim بۇ سایىتنى قوزغىتىپ تەكشۈرمەكتە… (ئاخىرقى سىناق: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim بۇ سایىتنى قوزغىتىپ تەكشۈرمەكتە… بۇ بەتنى قايتا يۈكلەڭ ياكى كۈنتەرتىپكە قويۇلغان تەكشۈرۈشنىڭ تاماملىنىشىنى كۈتۈڭ.','Babilim is not enabled.'=>'Babilim قوزغىتىلمىغان.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim قىستۇرما ئۆچۈرۈلگەندە بۇ تور بېكەتنىڭ كىملىكىنى ئۆچۈرۈۋېتىشكە تەڭشەلگەن. ئۇنىڭدىن كېيىن بۇ تور بېكەتكە باغلانغان ھەقلىق ئىجازەتنامىنى ئاپتوماتىك ئەسلىگە كەلتۈرگىلى بولمايدۇ؛ ئۇنى قايتۇرۇۋېلىش ئۈچۈن Babilim قوللىشى بىلەن %s ئارقىلىق ئالاقىلىشىشىڭىز كېرەك. كىملىكنى ساقلاپ قېلىش ئۈچۈن «ۋاز كېچىش» نى چېكىڭ، Babilim تەڭشەكلىرىدىكى «ئورنىتىلمىغاندا Babilim نىڭ بارلىق سانلىق مەلۇماتلىرىنى ئۆچۈرۈش» تاللانمىسىدىكى بەلگىنى ئېلىۋېتىڭ، ئاندىن قايتا توختىتىڭ. بەرىبىر توختىتامسىز؟','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim نىڭ بۇ بىر باسقۇچتىكى ۋاقتى توشتى، كېيىنكى تەكشۈرۈشتە داۋاملاشتۇرىدۇ.','Babilim settings'=>'Babilim تەڭشەكلىرى','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim ماس قەدەملەشتۈرۈشى مۇلازىمەت تەرىپىدىن ۋاقىتلىق كېچىكتۈرۈلدى (چەكلەندى)؛ %s دىن كېيىن قايتا سىنايدۇ.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'بۇ يوللاش ساقلاپ تۇرغاندا Babilim يېڭىلاندى. كونا بوغچا تاشلىۋېتىلدى؛ يوللاشنى قايتا جەزملەڭ.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim بۇ ھۆججەتلەرنى %1$s (نەشرى %2$s) دىن يوللايدۇ: ھەر بىر .php ۋە .js ھۆججىتى، ھەر بىر block.json ھۆججىتى، ھەمدە ئاساسىي قىسقۇچتىكى readme.txt، readme.md، style.css ۋە theme.json. ئۇلار تەرجىمە قىلىش كېرەك بولغان تېكىستنى تېپىش ھەمدە قىستۇرما ياكى ئۆرنەكنى پەرقلەندۈرۈش ئۈچۈن ئىشلىتىلىدۇ.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest ئىشلەتكىلى بولمايدۇ: %s','Back'=>'قايتىش','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'بۇ دائىرە نامى ئۈچۈن ئىجازەتنامە سېتىۋالغانمۇ؟ ھېسابلاشتا تاپشۇرۇۋالغان ئەسلىگە كەلتۈرۈش كودىنى كىرگۈزۈڭ.','Broken placeholder'=>'ئورۇن بەلگىسى بۇزۇلغان','Build'=>'قۇرۇلما','Built'=>'قۇرۇلغان','Bulk actions apply only to the selected language of each selected component.'=>'تۈركۈملەپ مەشغۇلات تاللانغان ھەر بىر زاپچاسنىڭ پەقەت تاللانغان تىلىغىلا قوللىنىلىدۇ.','Bulk actions apply to every matching language of each selected component.'=>'تۈركۈملەپ مەشغۇلات تاللانغان ھەر بىر زاپچاسنىڭ ماس كېلىدىغان بارلىق تىللىرىغا قوللىنىلىدۇ.','Bulk download:'=>'تۈركۈملەپ چۈشۈرۈش:','Bulk request:'=>'تۈركۈملەپ تەلەپ قىلىش:','Bulk update:'=>'تۈركۈملەپ يېڭىلاش:','Bundled with the plugin'=>'قىستۇرما بىلەن بىللە كەلگەن','Bundled with the theme'=>'ئۆرنەك بىلەن بىللە كەلگەن','By clicking Enable, you agree to send the information listed above to Babilim.'=>'«قوزغىتىش» نى چەككىنىڭىزدە، يۇقىرىدا كۆرسىتىلگەن ئۇچۇرلارنى Babilim غا ئەۋەتىشكە قوشۇلغان بولىسىز.','By continuing you confirm that you have the right to upload this component.'=>'داۋاملاشتۇرسىڭىز، بۇ بۆلەكنى يۈكلەشكە ھوقۇقىڭىز بارلىقىنى جەزملەشتۈرگەن بولىسىز.','Cancel'=>'ئەمەلدىن قالدۇرۇش','Category'=>'تۈر','Check again'=>'قايتا تەكشۈرۈش','Check again now'=>'ھازىر قايتا تەكشۈرۈش','Checkout is not available for this site right now.'=>'بۇ بېكەت ئۈچۈن ھازىر پۇل تۆلەش ئىقتىدارىنى ئىشلەتكىلى بولمايدۇ.','Choose'=>'تاللا','Choose a category…'=>'بىر تۈر تاللاڭ…','Choose a language'=>'بىر تىل تاللاڭ','Choose a language…'=>'تىل تاللاڭ…','Clear filters'=>'سۈزگۈچلەرنى تازىلاش','Close'=>'تاقا','Component'=>'بۆلەك','Confirm'=>'جەزملەش','Conflicting keys'=>'توقۇنۇشقان ئاچقۇچلار','Continue'=>'داۋاملاشتۇرۇش','Continue next batch (%d left)'=>'كېيىنكى تۈركۈمنى داۋاملاشتۇرۇش (%d قالدى)','Continuing…'=>'داۋاملاشتۇرۇلۇۋاتىدۇ…','Could not back up %s before replacing it.'=>'%s نى ئالماشتۇرۇشتىن بۇرۇن زاپاسلىغىلى بولمىدى.','Could not create the package archive.'=>'بوغچا ئارخىپىنى قۇرالمىدى.','Could not determine active components; the existing merged index was left unchanged.'=>'ئاكتىپ زاپچاسلارنى ئېنىقلىغىلى بولمىدى؛ مەۋجۇت بىرلەشتۈرۈلگەن ئىندېكس ئۆزگەرتىلمىدى.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'ئورنىتىلغان قىستۇرما/ئۆرنەكلەرنى ئېنىقلىغىلى بولمىدى؛ تازىلاش ئاتلاندى، ھېچنېمە ئۆچۈرۈلمىدى.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'مۇلازىمەتتىن WordPress.org نىڭ تولۇق تىل تىزىمىنى يۈكلىگىلى بولمىدى، شۇڭا ھازىر باشقا تىل قوشقىلى بولمايدۇ.','Could not move %s into place.'=>'%s نى ئورنىغا يۆتكىگىلى بولمىدى.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'\'%s\' ئۈچۈن بىرلەشتۈرۈلگەن ئىندېكسنى ئورنىغا يۆتكىگىلى بولمىدى؛ ئالدىنقى ئىشلىتىلىۋاتقان ئىندېكس (بولسا) يېرىم يېڭىلانغان ھالەتتە قالدۇرۇلماي ئۆچۈرۈلدى. كېيىنكى مۇۋەپپەقىyەتلىك قايتا قۇرۇشقىچە بۇ تىل ئۈچۈن سۈكۈتتىكى دائىرە تولۇقلىمىسى تەمىنلەنمەيدۇ.','Could not open zip: %s'=>'zip نى ئاچقىلى بولمىدى: %s','Could not prepare %s for rollback.'=>'%s نى ئەسلىگە قايتۇرۇشقا تەييارلىغىلى بولمىدى.','Could not read %s back after moving it into place.'=>'%s ئورنىغا يۆتكەلگەندىن كېيىن قايتا ئوقۇغىلى بولمىدى.','Could not read: %s'=>'ئوقۇغىلى بولمىدى: %s','Could not restore the purchase: %s'=>'سېتىۋېلىشنى ئەسلىگە كەلتۈرگىلى بولمىدى: %s','Could not show a new restore code: %s'=>'يېڭى ئەسلىگە كەلتۈرۈش كودىنى كۆرسىتەلمىدى: %s','Could not stage %s'=>'%s نى تەييارلىغىلى بولمىدى','Could not stage default/%s'=>'default/%s نى تەييارلىغىلى بولمىدى','Could not start checkout: %s'=>'پۇل تۆلەشنى باشلىغىلى بولمىدى: %s','Could not verify entry count for %s'=>'%s نىڭ تۈر سانىنى دەلىللىگىلى بولمىدى','Could not write the downloaded package to disk.'=>'چۈشۈرۈلگەن بوغچىنى دىسكىغا يازغىلى بولمىدى.','Could not write the staged merged index.'=>'باسقۇچلۇق بىرلەشتۈرۈلگەن ئىندېكسنى يازغىلى بولمىدى.','Current translation'=>'نۆۋەتتىكى تەرجىمە','Custom overrides'=>'ئىختىيارى قاپلاشلار','Danger zone'=>'خەتەرلىك رايون','Default supplement entry count mismatch.'=>'كۆڭۈلدىكى قوشۇمچە تۈر سانى ماس كەلمىدى.','Delete all Babilim data on uninstall'=>'ئورنىتىشتىن قالدۇرغاندا Babilim نىڭ بارلىق سانلىق مەلۇماتلىرىنى ئۆچۈرۈش','Disable Babilim'=>'Babilim نى چەكلەش','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim نى چەكلەمسىز؟ ئورنىتىلغان تەرجىمىلەر ساقلىنىدۇ، لېكىن بۇنىڭدىن كېيىن تەكشۈرۈش ياكى چۈشۈرۈش ئىجرا قىلىنمايدۇ.','Don\'t share'=>'ھەمبەھىرلىمە','Download'=>'چۈشۈرۈش','Downloaded and installed.'=>'چۈشۈرۈلۈپ ئورنىتىلدى.','Downloading…'=>'چۈشۈرۈلۈۋاتىدۇ…','Downloads: %1$d/%2$d (%3$s)'=>'چۈشۈرۈش: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'ھەر بىر بۆلەكنىڭ ھەر بىر تىلنىڭ ئورتاق سۈكۈتتىكى دائىرە تولۇقلىمىسىغا قوشقان ئۆز تۆھپىسى.','Enable Babilim'=>'Babilim نى قوزغىتىش','Enabling…'=>'قوزغىتىلىۋاتىدۇ…','English (United States)'=>'English (United States)','Entries'=>'تۈرلەر','Entry count mismatch for %s'=>'%s نىڭ تۈر سانى ماس كەلمىدى','Error reports'=>'خاتالىق دوكلاتلىرى','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'بۇ تور بېكەتتە ئىشلىتىلىۋاتقان بارلىق تىل-رايونلار (تور بېكەت تىل-رايونى، ئورنىتىلغان تىل بوغچىلىرى، ئىشلەتكۈچى تىل-رايونلىرى ۋە قولدا قوشقانلىرىڭىز). ھېچقانداق تىل-رايونغا ئالاھىدە مۇئامىلە قىلىنمايدۇ.','Excluded'=>'چىقىرىۋېتىلگەن','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'باشقا ئات ياكى كېڭەيتمىلىك ھۆججەتلەر، شۇنداقلا uploads، cache، logs، backup، data، vendor، node_modules ۋە languages قىسقۇچلىرى، يوشۇرۇن ھۆججەتلەر ياكى ئاتى ئادەتتىكى مەخپىي ھۆججەتلەرگە mos كېلىدىغان ھۆججەتلەر (wp-config*, .env*, *.sql, *.log, *.pem, *.key) كىرگۈزۈلمەيدۇ. كود ھۆججەتلىرىدە يەنىلا ھەمبەھىرلەشنى خالىمايدىغان تېكىست ياكى سانلىق مەلۇمات بولۇشى مۇمكىن؛ ئىشەنچسىز بولسىڭىز تەكشۈرۈپ بېقىڭ. مۇلازىمەت يېتىپ كەلگەندە ئوخشاش تۈردىكى ھۆججەتلەرنى يەنە بىر قېتىم چىقىرىۋېتىدۇ.','Fills in missing translations for the plugins and themes already installed on your site.'=>'تور بېكىتىڭىزدە ئورنىتىلغان قىستۇرمىلار ۋە ئۆرنەكلەرنىڭ كەم تەرجىمىلىرىنى تولدۇرىدۇ.','Free'=>'ھەقسىز','Free-plan slots'=>'ھەقسىز پىلان ئورۇنلىرى','General'=>'ئادەتتىكى','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'ئەگەر بۇ تاللانما قوزغىتىلسا، قىستۇرمىنى ئۆچۈرگەندە بۇ تور بېكەتنىڭ كىملىكىمۇ ئۆچۈرۈلىدۇ. ئۇنىڭدىن كېيىن بۇ تور بېكەتكە باغلانغان ھەقلىق ئىجازەتنامىنى ئاپتوماتىك ئەسلىگە كەلتۈرگىلى بولمايدۇ؛ ئۇنى قايتۇرۇۋېلىش ئۈچۈن Babilim قوللىشى بىلەن %s ئارقىلىق ئالاقىلىشىشىڭىز كېرەك.','Included'=>'كىرگۈزۈلگەن','Included in index'=>'ئىندېكسقا كىرگۈزۈلگەن','Install available translations automatically'=>'ئىشلەتكىلى بولىدىغان تەرجىمىلەرنى ئاپتوماتىك ئورنىتىش','Installed'=>'ئورنىتىلغان','Installed translations are kept, but no further checks or downloads will run.'=>'ئورنىتىلغان تەرجىمىلەر ساقلىنىدۇ، لېكىن بۇنىڭدىن كېيىن تەكشۈرۈش ياكى چۈشۈرۈش ئىجرا قىلىنمايدۇ.','Installed · %s'=>'ئورنىتىلدى · %s','Installed · built for %1$s, this site has %2$s'=>'قاچىلانغان · %1$s نەشرىگە ئاساسەن ياسالغان، بۇ تور بېكەتتە %2$s بار','Installed · built for %s'=>'قاچىلانغان · %s نەشرىگە ئاساسەن ياسالغان','Installed · built for %s, new version failed'=>'ئورنىتىلدى · %s نەشرىگە ئاتاپ ئىشلەنگەن، يېڭى نەشرى مەغلۇپ بولدى','Installed · built for %s, new version scheduled'=>'قاچىلانغان · %s نەشرىگە ئاساسەن ياسالغان، يېڭى نەشرى كۈنتەرتىپكە قويۇلدى','Installed · built for %s, translating the new version…'=>'قاچىلانغان · %s نەشرىگە ئاساسەن ياسالغان، يېڭى نەشرى تەرجىمە قىلىنىۋاتىدۇ…','Installed · built for %s; this plugin or theme is no longer covered by the site\'s service plan'=>'ئورنىتىلدى · %s ئۈچۈن قۇرۇلغان؛ بۇ قىستۇرما ياكى ئۆرنەك سايتنىڭ مۇلازىمەت پىلانى دائىرىسىدە ئەمەس','Installed · built for a different version'=>'قاچىلانغان · باشقا نەشرىگە ئاساسەن ياسالغان','Installed · built for a different version, new version failed'=>'ئورنىتىلدى · باشقا نەشرىگە ئاتاپ ئىشلەنگەن، يېڭى نەشرى مەغلۇپ بولدى','Installed · built for a different version, new version scheduled'=>'قاچىلانغان · باشقا نەشرىگە ئاساسەن ياسالغان، يېڭى نەشرى كۈنتەرتىپكە قويۇلدى','Installed · built for a different version, translating the new version…'=>'قاچىلانغان · باشقا نەشرىگە ئاساسەن ياسالغان، يېڭى نەشرى تەرجىمە قىلىنىۋاتىدۇ…','Installed · built for a different version; this plugin or theme is no longer covered by the site\'s service plan'=>'ئورنىتىلدى · باشقا نەشرى ئۈچۈن قۇرۇلغان؛ بۇ قىستۇرما ياكى ئۆرنەك سايتنىڭ مۇلازىمەت پىلانى دائىرىسىدە ئەمەس','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'ئۇ بۇ مۇلازىمەتنىڭ مۇلازىمېتىر ساھىبخانىلىق تەمىنلىگۈچىسى تەرىپىدىن ساقلىنىدۇ ھەمدە تەرجىمە ھاسىل قىلىش ئۈچۈن AI مودېللىرى تەرىپىدىن بىر تەرەپ قىلىنىدۇ.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'ھەممىنى تازىلىغاندا ياكى بۇ قىستۇرمىنى ئۆچۈرگەندە ئۆزۈم يازغان تەرجىمە قاپلاشلىرىمنى ساقلاپ قال.','Language'=>'تىل','Language:'=>'تىل:','Languages'=>'تىللار','Languages found on this site: %s.'=>'بۇ سایىتتا تېپىلغان تىللار: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'ئاخىرقى تازىلاش %1$s دە: %2$d يېڭىدىن بەلگىلەندى، %3$d ھۆججەت ئۆچۈرۈلدى، %4$d خاتىرە چىقىرىۋېتىلدى.','Maintenance'=>'ئاسراش','Maintenance status is not available right now.'=>'ئاسراش ھالىتىنى ھازىر كۆرگىلى بولمايدۇ.','Manifest unavailable: %s'=>'Manifest ئىشلەتكىلى بولمايدۇ: %s','Negation reversed'=>'ئىنكار مەنىسى ئەكسىچە بولۇپ قالغان','No'=>'ياق','No build is available to download for this locale.'=>'بۇ تىل ئۈچۈن چۈشۈرۈشكە بولىدىغان قۇرۇلما نەشرى يوق.','No cleanup has run yet.'=>'تېخى تازىلاش ئىجرا قىلىنمىدى.','No components match these filters. %s'=>'بۇ سۈزگۈچلەرگە ماس كېلىدىغان زاپچاس يوق. %s','No components synced yet.'=>'تېخى ھېچقانداق زاپچاس قەدەمداشلانمىدى.','No installed translation matches.'=>'ماس كېلىدىغان ئورنىتىلغان تەرجىمە يوق.','No language is managed yet.'=>'تېخى ھېچقانداق تىل باشقۇرۇلمايدۇ.','No pending challenge for this nonce.'=>'بۇ nonce ئۈچۈن كۈتۈۋاتقان خىرىس يوق.','No pending challenge to verify.'=>'دەلىللەشنى كۈتۈۋاتقان سىناق يوق.','No plugins or themes found.'=>'قوشۇلما ياكى ئۆرنەك تېپىلمىدى.','No previous build to roll back to.'=>'ئەسلىگە قايتۇرىدىغان ئالدىنقى قۇرۇلما نەشرى يوق.','No record for %s'=>'%s ئۈچۈن خاتىرە يوق','No site id is on file to rotate a token for.'=>'بەلگە (token) نى ئالماشتۇرىدىغان تور بېكەت ID سى خاتىرىلەنمىگەن.','No — component inactive'=>'ياق — بۆلەك ئاكتىپ ئەمەس','No — component removed'=>'ياق — بۆلەك ئۆچۈرۈلگەن','No — installed version differs from the active one'=>'ياق — ئورنىتىلغان نەشرى ئاكتىپ نەشرىدىن پەرقلىنىدۇ','Not a valid server_build_id: %s'=>'ئۈنۈملۈك server_build_id ئەمەس: %s','Not covered by the free service plan'=>'ھەقسىز مۇلازىمەت پىلانىغا كىرمەيدۇ','Not installed'=>'ئورنىتىلمىغان','Not registered yet'=>'تېخى تىزىملاتمىغان','Not supported'=>'قوللىمايدۇ','Not verified'=>'دەلىللەنمىگەن','Note (optional)'=>'ئىزاھات (ئىختىيارىي)','Nothing to choose.'=>'تاللايدىغان ھېچنېمە يوق.','Nothing to confirm.'=>'جەزملەيدىغان ھېچنېمە يوق.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'سۈكۈتتە ئېتىك: قىستۇرمىنى ئۆچۈرگەندە بۇ بېكەتنىڭ كىملىكى ساقلىنىدۇ، شۇڭا قايتا ئورنىتىلغاندا ئۇنى قايتا ئىشلەتكىلى بولىدۇ.','One or more served files no longer match the manifest.'=>'تارقىتىلغان بىر ياكى بىر قانچە ھۆججەت manifest غا ماس كەلمەيدۇ.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'بۇ تور بېكەت ئۈچۈن بىر قېتىملىق سېتىۋېلىش: %1$s %2$s. كېلەچەكتىكى بارلىق تەرجىمە يېڭىلانمىلىرىنى ئۆز ئىچىگە ئالىدۇ. چىقىم تۆلەش يېڭى بەتكۈچتە Paddle ئارقىلىق بىر تەرەپ قىلىنىدۇ.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'بۇنى پەقەت تور باشقۇرغۇچىسى قىلالايدۇ، چۈنكى بۇ مەزكۇر تورداتىكى بارلىق بېكەتلەر ئورتاق ئىشلىتىدىغان تەرجىمە ھۆججەتلىرىنى ئۆزگەرتىدۇ.','Only plugins and themes can be packaged.'=>'پەقەت قىستۇرمىلار ۋە ئۆرنەكلەرنىلا بوغچىلاشقا بولىدۇ.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'پەقەت سىز WordPress.org دا يوق قىستۇرما ياكى ئۆرنەكنىڭ ھۆججەتلىرىنى يوللاشنى جەزملەشتۈرگەندىلا: ھەر بىر .php ۋە .js ھۆججىتى، ھەر بىر block.json ھۆججىتى، ھەمدە شۇ زاپچاسنىڭ ئاساسىي قىسقۇچىدىكى readme.txt، readme.md، style.css ۋە theme.json، ئادەتتىكى مەخپىي ھۆججەتلەرگە ماس كېلىدىغان ھۆججەتلەر چىقىرىۋېتىلگەندىن كېيىن zip سۈپىتىدە يوللىنىدۇ.','Open Babilim settings'=>'Babilim تەڭشىكىنى ئېچىش','Original language'=>'ئەسلى تىل','Original string'=>'ئەسلى تېكىست','Paid'=>'ھەقلىق','Partner'=>'ھەمكارلاشقۇچى','Please check that your site can be reached from the internet, then try again.'=>'سایىتىڭىزنىڭ ئىنتېرنېتتىن زىيارەت قىلىنالايدىغانلىقىنى تەكشۈرۈپ، ئاندىن قايتا سىناڭ.','Please choose a category for this report.'=>'بۇ دوكلات ئۈچۈن بىر تۈر تاللاڭ.','Plugin'=>'قىستۇرما','Plugin · %s'=>'قوشۇلما · %s','Plugins'=>'قوشۇلمىلار','Preview'=>'ئالدىن كۆزەت','Purchase restored. This site is now licensed.'=>'سېتىۋېلىش ئەسلىگە كەلتۈرۈلدى. بۇ تور بېكەت ئەمدى ئىجازەتلىك.','Re-parsed entry count did not match the built index.'=>'قايتا ئانالىز قىلىنغان خاتىرە سانى قۇرۇلغان ئىندېكسقا ماس كەلمىدى.','Re-verify'=>'قايتا دەلىللەش','Rebuild index now'=>'ئىندېكسنى ھازىر قايتا قۇرۇش','Refusing to write outside the Babilim language-file directory.'=>'Babilim تىل ھۆججەت مۇندەرىجىسىنىڭ سىرتىغا يېزىشنى رەت قىلىدۇ.','Registration response was missing required fields.'=>'تىزىملىتىش جاۋابىدا زۆرۈر بۆلەكلەر كەم.','Registration restarted.'=>'تىزىملاتقۇزۇش قايتا باشلاندى.','Remove'=>'چىقىرىۋېتىش','Remove everything Babilim installed'=>'Babilim قاچىلىغان ھەممە نەرسىنى ئۆچۈرۈش','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Babilim قاچىلىغان ھەممە نەرسىنى ئۆچۈرۈشمۇ؟ بۇ ئۇنىڭ بۇ تور بېكەتتىكى ھەممە قىستۇرما ۋە ئۆرنەك ئۈچۈن قاچىلىغان بارلىق تىل ھۆججەتلىرىنى ئۆچۈرىدۇ.','Remove the %2$s translation of %1$s from this site?'=>'بۇ بېكەتتىن %1$s نىڭ %2$s تەرجىمىسى چىقىرىۋېتىلسۇنمۇ؟','Removed %d installed component.'=>'ئورنىتىلغان %d زاپچاس چىقىرىۋېتىلدى.' . "\0" . 'ئورنىتىلغان %d زاپچاس چىقىرىۋېتىلدى.','Removed after a failed integrity check'=>'پۈتۈنلۈكنى تەكشۈرۈش مەغلۇپ بولغاچقا ئۆچۈرۈلدى','Removed.'=>'ئۆچۈرۈلدى.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Babilim بۇ تور بېكەتتىكى ھەممە قىستۇرما ۋە ئۆرنەك ئۈچۈن قاچىلىغان بارلىق تىل ھۆججەتلىرىنى ئۆچۈرىدۇ.','Report a problem'=>'مەسىلە دوكلات قىلىش','Report translation'=>'تەرجىمىنى دوكلات قىلىش','Request newer translation'=>'يېڭىراق تەرجىمە تەلەپ قىلىش','Request translation'=>'تەرجىمە تەلەپ قىلىش','Requestable'=>'تەلەپ قىلغىلى بولىدىغان','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'تەرجىمە تەلەپ قىلسىڭىز، بۇ قىستۇرما ياكى ئۆرنەك بۇ تور بېكەتنىڭ ھەقسىز مۇلازىمەت پىلانىدىكى ئورۇنلارنىڭ بىرىگە ئورۇنلاشتۇرىلىدۇ (چەك: ئۆرنەكلەر ئۈچۈن %1$d، قىستۇرمىلار ئۈچۈن %2$d)، ئەگەر ئۇنىڭدا ئورۇن بولمىسا. ئورۇن ئىشلىتىلگەن ھالەتتە قالىدۇ، تەرجىمە مەغلۇپ بولسىمۇ ئورۇن بىكار قىلىنمايدۇ.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'تەرجىمە تەلەپ قىلسىڭىز، بۇ قىستۇرما ياكى ئۆرنەك بۇ تور بېكەتنىڭ ھەقسىز مۇلازىمەت پىلانىدىكى ئورۇنلارنىڭ بىرىگە ئورۇنلاشتۇرىلىدۇ، ئەگەر ئۇنىڭدا ئورۇن بولمىسا. ئورۇن ئىشلىتىلگەن ھالەتتە قالىدۇ، تەرجىمە مەغلۇپ بولسىمۇ ئورۇن بىكار قىلىنمايدۇ.','Requesting…'=>'تەلەپ قىلىنىۋاتىدۇ…','Restart registration'=>'تىزىملاشنى قايتا باشلاش','Restore code'=>'ئەسلىگە كەلتۈرۈش كودى','Restore purchase'=>'سېتىۋېلىشنى ئەسلىگە كەلتۈرۈش','Retry request'=>'تەلەپنى قايتا سىناش','Roll back'=>'ئەسلىگە قايتۇرۇش','Roll back and report'=>'ئەسلىگە قايتۇرۇپ دوكلات قىلىش','Roll back and send report'=>'ئەسلىگە قايتۇرۇپ دوكلات ئەۋەتىش','Roll back the %2$s translation of %1$s to the previous build?'=>'%1$s نىڭ %2$s تەرجىمىسىنى ئالدىنقى قۇرۇلما نەشرىگە قايتۇرامسىز؟','Rolled back and reported.'=>'قايتۇرۇلۇپ دوكلات قىلىندى.','Rolled back to the previous build.'=>'ئالدىنقى قۇرۇلما نەشرىگە قايتۇرۇلدى.','Rolled back, but the report could not be sent: %s'=>'قايتۇرۇلدى، لېكىن دوكلاتنى ئەۋەتكىلى بولمىدى: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'ئەسلىگە قايتۇرۇش \'%1$s\' (%2$s) نى قاپلىۋېتىدۇ، ئۇ ھازىر باشقا ئورنىتىلغان زاپچاس (%3$s) ئۈچۈن ئىشلىتىلىۋاتىدۇ؛ ھېچنېمە ئۆزگەرتىلمىدى.','Rotate-token response was missing site_token.'=>'بەلگىنى ئالماشتۇرۇش جاۋابىدا site_token كەم ئىكەن.','Save changes'=>'ئۆزگەرتىشلەرنى ساقلاش','Scheduled, waiting to be processed'=>'كۈنتەرتىپكە قويۇلغان، بىر تەرەپ قىلىنىشنى كۈتىۋاتىدۇ','Search'=>'ئىزدە','Search components'=>'زاپچاسلارنى ئىزدە','Search the installed translations'=>'ئورنىتىلغان تەرجىمىلەرنى ئىزدە','Select all'=>'ھەممىنى تاللاش','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'تېخىمۇ ئاز زاپچاس تاللاڭ: ھەر قېتىمدا ئەڭ كۆپ بولغاندا %1$d مەشغۇلات (سىز %2$d تاللىدىڭىز).','Send report'=>'دوكلات ئەۋەتىش','Service plan'=>'مۇلازىمەت پىلانى','Settings'=>'تەڭشەكلەر','Share error reports'=>'خاتالىق دوكلاتلىرىنى ھەمبەھىرلەش','Share this report'=>'بۇ دوكلاتنى ھەمبەھىرلەش','Show a new restore code'=>'يېڭى ئەسلىگە كەلتۈرۈش كودىنى كۆرسىتىش','Show the "Report translation" entry in the admin toolbar'=>'باشقۇرۇش قورال بالدىقىدا «تەرجىمىنى مەلۇم قىلىش» تۈرىنى كۆرسەت','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'بۇ زاپچاسنىڭ بەزى تېكىستلىرى ئاپتورى تەرىپىدىن قاتتىق كودلانغان بولۇپ، تىل بوغچىسى ئارقىلىق تەرجىمە قىلغىلى بولمايدۇ.','Status'=>'ھالەت','Status unknown'=>'ھالىتى نامەلۇم','String context'=>'تېكىستنىڭ تىل مۇھىتى','Suggested translation'=>'تەۋسىيە قىلىنغان تەرجىمە','Supplementary translation index'=>'تولۇقلىما تەرجىمە ئىندېكسى','Supplementary translation index rebuilt.'=>'قوشۇمچە تەرجىمە ئىندېكسى قايتا قۇرۇلدى.','Supplementary translation maintenance'=>'قوشۇمچە تەرجىمە ئىندېكسىنى ئاسراش','Supplementary translations'=>'تولۇقلىما تەرجىمىلەر','Sweep aborted without orphaning anything: %s.'=>'تازىلاش ھېچقانداق نەرسىنى يېتىم قىلماستىن توختىتىلدى: %s.','Sweep complete: %d file deleted.'=>'تازىلاش تامام بولدى: %d ھۆججەت ئۆچۈرۈلدى.' . "\0" . 'تازىلاش تامام بولدى: %d ھۆججەت ئۆچۈرۈلدى.','Sweep now'=>'ھازىر تازىلاش','Sync complete.'=>'ماس قەدەملەش تامام بولدى.','Thank you. Your report was sent.'=>'رەھمەت. دوكلاتىڭىز ئەۋەتىلدى.','That component is not installed on this site, so a translation cannot be requested for it.'=>'بۇ زاپچاس بۇ تور بېكەتتە ئورنىتىلمىغان، شۇڭلاشقا ئۇنىڭ ئۈچۈن تەرجىمە تەلەپ قىلغىلى بولمايدۇ.','That does not look like a restore code.'=>'بۇ ئەسلىگە كەلتۈرۈش كودىغا ئوخشىمايدۇ.','That is not a valid WordPress locale code. Nothing was saved.'=>'بۇ ئىناۋەتلىك WordPress تىل كودى ئەمەس. ھېچنېمە ساقلانمىدى.','That is not a valid build identifier.'=>'بۇ ئىناۋەتلىك قۇرۇلما نەشرى ID سى ئەمەس.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'بۇ يوللاش ئېكرانى ۋاقتى ئۆتكەن: ئۇنىڭدىن كېيىن باشقا بىر يوللاش تەييارلانغان. ھېچنېمە ئەۋەتىلمىدى. نۆۋەتتىكىسىنى تەرجىمە تىزىمliكىدىن كۆرۈپ چىقىڭ.','The change could not be recorded in the translation index; please try again.'=>'بۇ ئۆزگەرتىشنى تەرجىمە ئىندېكسىغا خاتىرىلىگىلى بولمىدى؛ قايتا سىناپ بېقىڭ.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'تازىلاش ئىجرا قىلىندى، لېكىن بەزى ئۆزگىرىشلەرنى تەرجىمە ئىندېكسىغا خاتىرىلىگىلى بولمىدى؛ كېيىنكى تازىلاشتا قايتا سىنىلىدۇ.','The component has no files that can be uploaded.'=>'بۇ زاپچاستا يوللىغىلى بولىدىغان ھۆججەت يوق.','The component is not inside the plugins or themes directory.'=>'زاپچاس قىستۇرمىلار ياكى ئۆرنەكلەر مۇندەرىجىسىنىڭ ئىچىدە ئەمەس.','The component\'s main file was not found.'=>'زاپچاسنىڭ ئاساسىي ھۆججىتى تېپىلمىدى.','The download response was missing a usable location.'=>'چۈشۈرۈش جاۋابىدا ئىشلەتكىلى بولىدىغان ئورۇن يوق ئىكەن.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'بۇ تۈر Babilim بۇ بېكەتتە ئورنىتىپ قويغان تەرجىمىلەرنى ئىزدەپ، ئۇلارنىڭ بىرىنى مەلۇم قىلىش ئۈچۈن بىر تاختا ئاچىدۇ.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'"%1$s" مەيدانى بەك ئۇزۇن: ئۇ %2$d ھەرپتىن تەركىب تاپقان، چەك بولسا %3$d. ھېچنېمە ئەۋەتىلمىدى؛ قىسقارتىپ قايتا سىناڭ.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'ھەقسىز مۇلازىمەت پىلانى ھەر بىر تور بېكەتكە قىستۇرما ۋە ئۆرنەكلەر ئۈچۈن چەكلىك ساندىكى ئورۇن بېرىدۇ؛ ئىشلىتىلىۋاتقان ئورۇنلار Babilim نى قوزغاتقاندىن كېيىن تەڭشەكلەردە كۆرسىتىلىدۇ.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'بېرىلگەن دائىرە \'%1$s\' بوغچا manifest ىنىڭ ئۆزىنىڭ slug قىممىتى \'%2$s\' غىمۇ، text_domain قىممىتى \'%3$s\' غىمۇ ماس كەلمىدى.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'\'%s\' ئۈچۈن بىرلەشتۈرۈلگەن ئىندېكس قايتا قۇرۇلدى، لېكىن تەرجىمە ئىندېكسى ئۇنى خاتىرىلىيەلمىدى؛ كېيىنكى قايتا قۇرۇش قايتا سىنايدۇ.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'ئەسلى تېكىست ۋە ئۇنىڭدىن ياسالغان تەرجىمىلەر ئوخشاش نەشرىنى قاچىلىغان باشقا تور بېكەتلەرگە تەمىنلىنىدۇ.','The package declares no main translation file.'=>'بۇ بوغچىدا ئاساسىي تەرجىمە ھۆججىتى جاكارلانمىغان.','The package has no %s for its own text domain.'=>'بوغچىدا ئۆزىنىڭ تېكىست دائىرىسى (text domain) ئۈچۈن %s يوق.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'بوغچا manifest ىنىڭ تۈرى \'%1$s\' تەلەپ قىلىنغان تۈر \'%2$s\' غا ماس كەلمىدى.','The package produced no servable main translation file.'=>'بۇ بوغچىدىن تارقىتىشقا بولىدىغان ئاساسىي تەرجىمە ھۆججىتى چىقمىدى.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'بوغچىنىڭ تېكىست دائىرىسى (text domain) \'%1$s\' بۇ بېكەتتىكى بۇ زاپچاسنىڭ (\'%2$s\') نۇسخىسىغا ماس كەلمىدى، شۇڭا ئورنىتىلمىدى.','The packaged component could not be read.'=>'بوغچىلانغان زاپچاسنى ئوقۇغىلى بولمىدى.','The registration challenge is not in the expected form.'=>'تىزىملاتقۇزۇش سىنىقى مۆلچەرلەنگەن شەكىلدە ئەمەس.','The report could not be sent.'=>'دوكلاتنى ئەۋەتكىلى بولمىدى.','The search could not be completed.'=>'ئىزدەشنى تاماملىغىلى بولمىدى.','The service asked this site to wait before syncing again.'=>'مۇلازىمەت بۇ بېكەتتىن قايتا ماسقەدەملەشتىن بۇرۇن ساقلاشنى تەلەپ قىلدى.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'مۇلازىمەت سایىتىڭىزغا ئۇلىنالمىدى. ئوت تامى، بىخەتەرلىك قىستۇرمىسى ياكى ساھىبجاي قائىدىسى تەلەپنى توسۇۋاتقان بولۇشى مۇمكىن؛ /wp-json/babilim/v1/challenge غا بولغان تەلەپلەرگە يول قويۇڭ.','The service\'s upload offer was incomplete.'=>'مۇلازىمەتنىڭ يۈكلەش تەكلىپى تولۇق ئەمەس ئىكەن.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'تېكىست دائىرىسى (text domain) \'%1$s\' (%2$s) باشقا ئورنىتىلغان زاپچاس (%3$s) ئۈچۈن ئىشلىتىلىۋاتىدۇ؛ ھېچنېمە ئورنىتىلمىدى.','The upload is kept until you ask Babilim to delete it.'=>'يۈكلەنگەن مەزمۇن سىز Babilim دىن ئۆچۈرۈشنى تەلەپ قىلغانغا قەدەر ساقلىنىدۇ.','Theme'=>'ئۆرنەك','Theme · %s'=>'ئۆرنەك · %s','Themes'=>'ئۆرنەكلەر','There is no upload in progress.'=>'ئىجرا بولۇۋاتقان يۈكلەش يوق.','There is no upload waiting for confirmation.'=>'جەزملەشنى كۈتىۋاتقان يۈكلەش يوق.','These are the languages this site uses. You can change them in %s.'=>'بۇلار بۇ تور بېكەت ئىشلىتىدىغان تىللار. ئۇلارنى %s ئارقىلىق ئۆزگەرتەلەيسىز.','These fields will be sent:'=>'تۆۋەندىكى بۆلەكلەر ئەۋەتىلىدۇ:','This build is not one this site currently knows about for this component/locale.'=>'بۇ قۇرۇلما نەشرى بۇ تور بېكەتنىڭ ھازىر بۇ زاپچاس/تىل ئۈچۈن بىلىدىغان نەشرى ئەمەس.','This component does not declare a version number, so a translation cannot be requested for it.'=>'بۇ زاپچاس نەشر نومۇرىنى ئاشكارىلىمىغان، شۇڭلاشقا ئۇنىڭ ئۈچۈن تەرجىمە تەلەپ قىلغىلى بولمايدۇ.','This component is larger than the service accepts, so it cannot be uploaded.'=>'بۇ زاپچاس مۇلازىمەت قوبۇل قىلىدىغان چوڭلۇقتىن ئېشىپ كەتتى، شۇڭا يوللىغىلى بولمايدۇ.','This component was already uploaded. Babilim is checking it now.'=>'بۇ زاپچاس ئاللىقاچان يۈكلەنگەن. Babilim ھازىر ئۇنى تەكشۈرۈۋاتىدۇ.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'بۇ زاپچاسنىڭ نەشر نومۇرى %d ھەرپتىن ئۇزۇن، Babilim ئۇنى بىر تەرەپ قىلالمايدۇ، شۇڭلاشقا ئۇنىڭ ئۈچۈن تەرجىمە تەلەپ قىلغىلى بولمايدۇ.','This issues a new restore code and the previous one stops working. Continue?'=>'بۇ يېڭى ئەسلىگە كەلتۈرۈش كودى بېرىدۇ، ئالدىنقى كود ئىناۋەتسىز بولىدۇ. داۋاملاشتۇرامسىز؟','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'بۇ كۆپ تور بېكەتلىك تور (network) تا تور بېكەتلەر بەك كۆپ بولغاچقا، ئۇلارنى بىرمۇبىر تەكشۈرگىلى بولمايدۇ، ئۇلارنىڭ بەزىلىرى قىستۇرما ئۆچۈرۈلگەندە Babilim كىملىكىنى ئۆچۈرۈۋېتىشكە تەڭشەلگەن بولۇشى مۇمكىن. ئۇنداق تور بېكەتكە باغلانغان ھەقلىق ئىجازەتنامىنى ئاپتوماتىك ئەسلىگە كەلتۈرگىلى بولمايدۇ؛ ئۇنى قايتۇرۇۋېلىش ئۈچۈن Babilim قوللىشى بىلەن %s ئارقىلىق ئالاقىلىشىشىڭىز كېرەك. كىملىكلەرنى ساقلاپ قېلىش ئۈچۈن «ۋاز كېچىش» نى چېكىڭ، ھەر بىر تور بېكەتنىڭ Babilim تەڭشەكلىرىدىكى «ئورنىتىلمىغاندا Babilim نىڭ بارلىق سانلىق مەلۇماتلىرىنى ئۆچۈرۈش» تاللانمىسىدىكى بەلگىنى ئېلىۋېتىڭ، ئاندىن قايتا توختىتىڭ. بەرىبىر توختىتامسىز؟','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'بۇ قىستۇرمىنىڭ ئۆز نەشرى، شۇنداق بولغاندا ئۇ بەك كونا بولۇپ مۇلازىمەت بىلەن ئالاقىلىشالمىسا، مۇلازىمەت سىزگە يېڭىلاشنى ئېيتالايدۇ.','This report does not name a valid plugin or theme and locale.'=>'بۇ دوكلاتتا ئىناۋەتلىك قىستۇرما ياكى ئۆرنەك ۋە تىل ئېنىق كۆرسىتىلمىگەن.','This report does not name an installed string.'=>'بۇ دوكلاتتا ئورنىتىلغان بىرەر تېكىست ئاتالمىدى.','This report is missing a valid build to report against.'=>'بۇ دوكلاتقا ماس كېلىدىغان ئىناۋەتلىك قۇرۇلما نەشرى يوق.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'بۇ دوكلات GitHub دا ئاشكارا ئېلان قىلىنىدۇ ھەمدە ئۈچىنچى تەرەپلەر ساقلاپ قويۇشى مۇمكىن.','This restore code was not recognised for this site.'=>'بۇ ئەسلىگە كەلتۈرۈش كودى مەزكۇر بېكەتتە تونۇلمىدى.','This site already has an active registration that can no longer be recovered automatically.'=>'بۇ بېكەتتە ئاپتوماتىك ئەسلىگە كەلتۈرگىلى بولمايدىغان ئاكتىپ تىزىملىتىش بار.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'بۇ بېكەتتە %2$d تىلدا %1$d زاپچاس بار، %3$d تەكشۈرۈش تۈركۈمى لازىم؛ Babilim ھەر قېتىمدا ئەڭ كۆپ بولغاندا %4$d نى بىر تەرەپ قىلالايدۇ. تەڭشەكلەردە باشقۇرۇلىدىغان تىللارنى ئازايتىڭ ياكى ئىشلىتىلمەيدىغان قىستۇرما ۋە ئۆرنەكلەرنى چەكلەڭ، ئاندىن ھازىر قايتا تەكشۈرۈش نى بېسىڭ.','This site has no purchase to show a code for.'=>'بۇ تور بېكەتتە كود كۆرسىتىدىغان سېتىۋېلىش يوق.','This site is already licensed. Reload the page.'=>'بۇ بېكەتنىڭ ئىجازەتنامىسى بار. بەتنى قايتا يۈكلەڭ.','This site is not registered with Babilim yet.'=>'بۇ بېكەت تېخى Babilim غا تىزىملاتمىغان.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'بۇ سایىتنىڭ چوڭلۇقى مۇلازىمەت بىر قېتىملىق قەدەمداشلاشتا قوبۇل قىلىدىغان چەكتىن ئېشىپ كەتتى، شۇڭا بەزى تۈرلەر قالدۇرۇلدى: %1$d زاپچاس ۋە %2$d تىل.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'بۇ بېكەت كۆپ بېكەتلىك تورنىڭ بىر قىسمى بولۇپ، يېڭى تەرجىمىلەر ئاپتوماتىك ئورنىتىلمايدۇ. ئورنىتىلغان تەرجىمىلەر يەنىلا يېڭىلىنىدۇ.','This site is verified.'=>'بۇ سایىت دەلىللەندى.','This site must be verified first.'=>'بۇ تور بېكەتنى ئالدىدا دەلىللەش كېرەك.','This site\'s URL, so the service can verify you own it.'=>'بۇ تور بېكەتنىڭ URL ئادرېسى، شۇنداق بولغاندا مۇلازىمەت ئۇنىڭ سىزگە تەۋە ئىكەنلىكىنى دەلىللىيەلەيدۇ.','This site\'s address is too long for Babilim to register.'=>'بۇ تور بېكەتنىڭ ئادرېسى بەك ئۇزۇن، Babilim تىزىملىتالمايدۇ.','This site\'s configured locale.'=>'بۇ تور بېكەتنىڭ تەڭشەلگەن تىل-رايونى.','This site\'s locale code is not one Babilim can register.'=>'بۇ تور بېكەتنىڭ تىل كودىنى Babilim تىزىملىتالمايدۇ.','This string can\'t be reported from this site.'=>'بۇ تېكىستنى بۇ بەتتىن دوكلات قىلغىلى بولمايدۇ.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'بۇ تېكىست بۇ تور بېتىگە ئورنىتىلغان تەرجىمىلەر ئىچىدە يوق. قايتا ئىزدەپ، تىزىمدىن تاللاڭ.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'بۇ تەرجىمە سىز ئىزدىگەندىن كېيىن يېڭىلاندى. قايتا ئىزدەپ، يېڭى تىزىمدىن تېكىستنى تاللاڭ.','To translate this component, Babilim needs its source.'=>'بۇ بۆلەكنى تەرجىمە قىلىش ئۈچۈن Babilim نىڭ ئۇنىڭ مەنبەسى بولۇشى كېرەك.','Too many attempts. Try again tomorrow.'=>'سىناش قېتىم سانى بەك كۆپ. ئەتە قايتا سىناڭ.','Too many reports today. Try again tomorrow.'=>'بۈگۈن دوكلات بەك كۆپ بولدى. ئەتە قايتا سىناڭ.','Too many requests.'=>'تەلەپ بەك كۆپ.','Toolbar'=>'قورال بالدىقى','Translating…'=>'تەرجىمە قىلىنىۋاتىدۇ…','Translation does not load'=>'تەرجىمە يۈكلەنمەيدۇ','Translation failed'=>'تەرجىمە مەغلۇپ بولدى','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'سىز %s غا قويغان تەرجىمە ھۆججەتلىرى ھەمىشە Babilim نىڭكىدىن ئاۋۋال ئىشلىتىلىدۇ. بۇ تاللاشنى بىكار قىلمىسىڭىز ئۇلار ساقلىنىدۇ.','Translation requested.'=>'تەرجىمە تەلەپ قىلىندى.','Translations'=>'تەرجىمىلەر','Type'=>'تىپى','Type at least 2 characters to search.'=>'ئىزدەش ئۈچۈن كەم دېگەندە 2 ھەرپ كىرگۈزۈڭ.','Unexpected HTTP %d response.'=>'كۈتۈلمىگەن HTTP %d ئىنكاسى.','Uninstall'=>'ئورنىتىشنى ئۆچۈرۈش','Unknown kind: %s'=>'نامەلۇم تۈر: %s','Unsafe domain: %s'=>'بىخەتەر بولمىغان دائىرە: %s','Unsafe locale: %s'=>'بىخەتەر بولمىغان تىل-رايون: %s','Unsafe slug: %s'=>'بىخەتەر بولمىغان slug: %s','Unsafe text_domain: %s'=>'بىخەتەر بولمىغان text_domain: %s','Update'=>'يېڭىلاش','Update available'=>'يېڭىلاش بار','Updates'=>'يېڭىلانمىلار','Updating…'=>'يېڭىلىنىۋاتىدۇ…','Upgrade this site'=>'بۇ بېكەتنى يۈكسەلدۈرۈش','Upload and request'=>'يۈكلەپ تەلەپ قىلىش','Upload cancelled.'=>'يۈكلەش بىكار قىلىندى.','Upload complete — translation requested.'=>'يۈكلەش تامام — تەرجىمە تەلەپ قىلىندى.','Upload expired before it finished'=>'يۈكلەش ۋاقتى توشتى، تاماملانمىدى','Upload in progress — continue or cancel'=>'يۈكلەش داۋاملىشىۋاتىدۇ — داۋاملاشتۇرۇڭ ياكى بىكار قىلىڭ','Upload this component?'=>'بۇ زاپچاسنى يۈكلەمسىز؟','Upload was not accepted'=>'يۈكلەش قوبۇل قىلىنمىدى','Uploading'=>'يۈكلىنىۋاتىدۇ','Uploading part %1$d of %2$d…'=>'%2$d پارچىنىڭ %1$d-پارچىسى يۈكلىنىۋاتىدۇ…','Uploading…'=>'يۈكلىنىۋاتىدۇ…','Verified'=>'دەلىللەنگەن','Verify response was missing site_token.'=>'دەلىللەش جاۋابىدا site_token كەم ئىكەن.','Version %s'=>'نەشرى %s','What is sent when you enable Babilim'=>'Babilim نى قوزغاتقاندا ئەۋەتىلىدىغان مەزمۇن','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Babilim ئىچىدە بىرەر نەرسە مەغلۇپ بولغاندا، خاتالىق دوكلاتىنى Babilim مۇلازىمىتىگە ئەۋەتىپ، GitHub تا ئاشكارا مەسىلە سۈپىتىدە ئېلان قىلىدۇ. دوكلات مۇشۇ بەتتىن كەلگەندەك ئەۋەتىلىدۇ، Babilim مۇلازىمىتىگە يوللانغان باشقا ھەر بىر ئىلتىماس بىلەن ئوخشاش دەلىللەش ئىشلىتىلىدۇ. مۇلازىمەت پەقەت خاتالىق كودى ۋە نەشرىنىلا GitHub تا ئاشكارا مەسىلە سۈپىتىدە ئېلان قىلىدۇ؛ ئاشكارا مەسىلىدە بەت ئادرېسى، مەزمۇن ياكى ھۆججەت يولى بولمايدۇ. كۆڭۈلدىكىدەك تاقاق.','Where you saw this (optional)'=>'بۇنى قەيەردە كۆردىڭىز (ئىختىيارىي)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'بۇ ئوچۇق ۋاقىتتا، مۇلازىمەت سىز باشقۇرىدىغان تىللار ئۈچۈن بار دەپ كۆرسەتكەن تەرجىمىلەر كۈنىگە ئىككى قېتىم ماسقەدەملەش جەريانىدا قاچىلىنىدۇ.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'بۇ مەزمۇنغا ماس كەلمەيدۇ','Wrong meaning'=>'مەنىسى خاتا','Wrong plural form'=>'خاتا كۆپلۈك شەكلى','Wrong term'=>'ئاتالغۇ خاتا','Yes'=>'ھەئە','You are not allowed to do this.'=>'سىزنىڭ بۇ مەشغۇلاتنى ئىجرا قىلىشىڭىزغا رۇخسەت يوق.','Your PHP version, for compatibility.'=>'PHP نەشرىڭىز، ماسلىشىشچانلىقنى جەزملەش ئۈچۈن.','Your WordPress version, to serve compatible translation files.'=>'WordPress نەشرىڭىز، ماسلىشىدىغان تەرجىمە ھۆججەتلىرىنى تەمىنلەش ئۈچۈن.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'يېڭى ئەسلىگە كەلتۈرۈش كودىڭىز: %s. ئۇنى بىخەتەر جايدا ساقلاڭ — ئالدىنقى كود ئىناۋەتسىز بولدى.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'دوكلاتىڭىز AI مودېللىرى تەرىپىدىن ئاپتوماتىك بىر تەرەپ قىلىنىدۇ ھەمدە بۇ تەرجىمىنى باشقا بەتلەر ئۈچۈن ياخشىلىشى مۇمكىن.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'تور بېكىتىڭىز جاۋاب قايتۇردى، ئەمما كۈتكەن مەزمۇن ئەمەس. REST API باشقا قىستۇرما تەرىپىدىن قايتا يېزىلغان بولۇشى ياكى بۇ ئۇلانما ۋاقىتلىق ساقلانغان بولۇشى مۇمكىن؛ /wp-json/babilim/v1/challenge نى ۋاقىتلىق ساقلاش ۋە قايتا يېزىشتىن مۇستەسنا قىلىڭ.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'سایىتىڭىزنىڭ جاۋاب قايتۇرۇشىغا بەك ئۇزۇن ۋاقىت كەتتى. سەل تۇرۇپ قايتا سىناڭ، ھەمدە ساھىبجايىڭىزنىڭ بەك ئاستا ئەمەسلىكىنى ياكى ھەددىدىن زىيادە يۈكلەنمىگەنلىكىنى تەكشۈرۈڭ.','Zip has no manifest.json.'=>'Zip ئىچىدە manifest.json يوق.','Zip is missing expected default file: %s'=>'Zip ئىچىدە كۈتۈلگەن كۆڭۈلدىكى ھۆججەت يوق: %s','Zip is missing expected file: %s'=>'Zip ئىچىدە كۈتۈلگەن ھۆججەت يوق: %s','_manifest.json has an unexpected structure'=>'_manifest.json نىڭ قۇرۇلمىسى كۈتۈلگەنگە ماس كەلمەيدۇ','could not read _manifest.json: %s'=>'_manifest.json نى ئوقۇغىلى بولمىدى: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest دا \'%s\' يوق ياكى ئۈنۈمسىز.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest دىكى \'server_build_id\' ئۈنۈملۈك قۇرۇلما نەشرى ID سى ئەمەس.','failed to parse _manifest.json: %s'=>'_manifest.json نى تەھلىل قىلىش مەغلۇپ بولدى: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'باشقۇرۇلىدىغان %2$d زاپچاسنىڭ %1$d ىنى يېتىم قىلىپ قويىدۇ (yېرىمىدىن كۆپ)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'بارلىق باشقۇرۇلىدىغان %1$s زاپچاسلىرىنى (%2$d نىڭ %2$d ى) يېتىم قىلىپ قويىدۇ','l10n.php entry count mismatch for %s'=>'%s نىڭ l10n.php مەزمۇن سانى ماس كەلمىدى','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json دىكى \'default_domain_entries\' ئۈنۈمسىز.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json دىكى \'default_domain_files\' ئۈنۈمسىز.','manifest.json in the zip is not valid JSON.'=>'zip ئىچىدىكى manifest.json ئۈنۈملۈك JSON ئەمەس.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json دا \'%s يوق ياكى ئۈنۈمسىز.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json دا \'build_no\' يوق ياكى ئۈنۈمسىز.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json دا \'entries\' يوق ياكى ئۈنۈمسىز.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json دا \'extra_domains\' يوق ياكى ئۈنۈمسىز.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json دا \'files\' يوق ياكى ئۈنۈمسىز.','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json دىكى \'%s\' كۈتۈلگەن قىممەتكە ماس كەلمىدى.','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json دىكى \'contract\' ئۈنۈملۈك نەشر تىزمىسى ئەمەس.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json دىكى \'kind\' چوقۇم \'plugin\' ياكى ئۆرنەك (\'theme\') بولۇشى كېرەك.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json دىكى \'server_build_id\' ئۈنۈملۈك قۇرۇلما نەشرى ID سى ئەمەس.','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json دىكى \'status\' چوقۇم \'published\' بولۇشى كېرەك.','nonce must be a hexadecimal string.'=>'nonce چوقۇم ئون ئالتىلىك تىزما بولۇشى كېرەك.','per day'=>'ھەر كۈنى','rc_…'=>'rc_…','sha256 mismatch for %s'=>'%s نىڭ sha256 ماس كەلمىدى','sha256 mismatch for default/%s'=>'default/%s نىڭ sha256 ماس كەلمىدى','component kind in the sweep brake messageplugin'=>'قىستۇرما','component kind in the sweep brake messagetheme'=>'ئۆرنەك','problem report categoryOther'=>'باشقا','translation statusAvailable'=>'ئىشلەتكىلى بولىدۇ','translation statusInstalled'=>'قاچىلانغان','Babilim translation turned off.'=>'Babilim تەرجىمىسى تاقالدى.','Stop using Babilim translation'=>'Babilim تەرجىمىسىنى ئىشلىتىشنى توختىتىش','Use Babilim translation'=>'Babilim تەرجىمىسىنى ئىشلىتىش','Stop using the Babilim translation of %1$s (%2$s)? WordPress will use the theme\'s own or WordPress.org translation instead. You can switch back at any time.'=>'%1$s (%2$s) نىڭ Babilim تەرجىمىسىنى ئىشلىتىشنى توختىتامسىز؟ WordPress ئۇنىڭ ئورنىغا ئۆرنەكنىڭ ئۆزىنىڭ ياكى WordPress.org تەرجىمىسىنى ئىشلىتىدۇ. خالىغان ۋاقىتتا قايتا ئالماشتۇرالايسىز.','Stop using the Babilim translation of %1$s (%2$s)? WordPress will use the plugin\'s own or WordPress.org translation instead. You can switch back at any time.'=>'%1$s (%2$s) نىڭ Babilim تەرجىمىسىنى ئىشلىتىشنى توختىتامسىز؟ WordPress ئۇنىڭ ئورنىغا قىستۇرمىنىڭ ئۆزىنىڭ ياكى WordPress.org تەرجىمىسىنى ئىشلىتىدۇ. خالىغان ۋاقىتتا قايتا ئالماشتۇرالايسىز.','Babilim – Auto-Translate Plugins & Themes'=>'Babilim – Auto-Translate Plugins & Themes','Enjoying Babilim? Please leave a rating on WordPress.org.'=>'Babilim نى ياقتۇردىڭىزمۇ؟ WordPress.org تا باھا بېرىپ قويۇڭ.','Rate Babilim'=>'Babilim غا باھا بېرىش','Babilim translation bundled with the theme'=>'ئۆرنەك بىلەن بىللە بولغان Babilim تەرجىمىسى','Babilim translation bundled with the plugin'=>'قىستۇرما بىلەن بىللە بولغان Babilim تەرجىمىسى','For every installed plugin and theme: its name (slug), version, text domain, whether it is listed on WordPress.org, the languages it already includes, and which of those bundled translations Babilim generated (language codes only). For each Babilim translation you have installed: which version it is, when it was last checked, and whether it passed its file check.'=>'ئورنىتىلغان ھەر بىر قىستۇرما ۋە ئۆرنەك ئۈچۈن: ئۇنىڭ نامى (قىسقا ئىسىم (slug))، نەشرى، text domain، WordPress.org تىزىملىكىدە بار-يوقلۇقى، ئۆزىدە بار تىللار، ھەمدە ئۆزىدىكى بۇ تەرجىمىلەردىن قايسىسىنىڭ Babilim تەرىپىدىن ھاسىل قىلىنغانلىقى (پەقەت تىل كودلىرى). ئورنىتىلغان ھەر بىر Babilim تەرجىمىسى ئۈچۈن: ئۇنىڭ قايسى نەشرى ئىكەنلىكى، ئاخىرقى قېتىم قاچان تەكشۈرۈلگەنلىكى ۋە ھۆججەت تەكشۈرۈشتىن ئۆتكەن-ئۆتمىگەنلىكى.']];